export function getIcon(name: string, style: IconStyle, fill: boolean): IconVariant | null {
  const family = ICONS[name]?.[style] ?? ICONS[name]?.outlined;
  if (!family) return null;
  const key: IconFill = fill ? "fill1" : "default";
  return family[key] ?? family.fill1 ?? family.default ?? null;
}

